    "dayDescription": { "t": 0, "b": { "t": 2, "i": [{ "t": 3 }], "s": "Retourne le jour de la date en argument en tant qu'entier compris entre 1 et 31." } },
    "dateDiffDescription": { "t": 0, "b": { "t": 2, "i": [{ "t": 3 }], "s": "\xC9tant donn\xE9 l'unit\xE9 de mesure d\xE9finie par le premier argument ('year', 'month', 'week', 'day', 'hour', 'minute', 'seconds') calcule et retourne le nombre d'unit\xE9 pour aller du second argument au troisi\xE8me." } },
